import sys
import math

# 8방향 스핀 델타값
d_p = [-1, -1, 0, 1, 1, 1, 0, -1]
d_q = [0, 1, 1, 1, 0, -1, -1, -1]


class Qubit:
    __slots__ = ['p', 'q', 'p_prev', 'q_prev', 'E', 'v', 'theta', 'has_history']

    def __init__(self, p, q, E, v, theta, p_prev=-1, q_prev=-1, has_history=False):
        self.p = p
        self.q = q
        self.p_prev = p_prev
        self.q_prev = q_prev
        self.E = E
        self.v = v
        self.theta = theta
        self.has_history = has_history


def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    N = int(next(iterator))
    M = int(next(iterator))
    Q = int(next(iterator))
    Phi = int(next(iterator))
    W = int(next(iterator))

    space = {}

    for _ in range(M):
        p = int(next(iterator))
        q = int(next(iterator))
        E = int(next(iterator))
        v = int(next(iterator))
        theta = int(next(iterator))
        if (p, q) not in space:
            space[(p, q)] = []
        space[(p, q)].append(Qubit(p, q, E, v, theta))

    wormholes = set()
    for _ in range(W):
        pw = int(next(iterator))
        qw = int(next(iterator))
        wormholes.add((pw, qw))

    def in_range(val, c1, c2):
        if c1 <= c2:
            return c1 <= val <= c2
        return val >= c1 or val <= c2

    for _ in range(Q):
        type_q = int(next(iterator))

        if type_q == 1:
            k_steps = int(next(iterator))
            for _ in range(k_steps):
                new_space = {}
                for (p, q), qubits in space.items():
                    for qb in qubits:
                        qb.p_prev = qb.p
                        qb.q_prev = qb.q
                        qb.has_history = True

                        qb.p = (qb.p + qb.v * d_p[qb.theta]) % N
                        qb.q = (qb.q + qb.v * d_q[qb.theta]) % N

                        loc = (qb.p, qb.q)
                        if loc not in new_space:
                            new_space[loc] = []
                        new_space[loc].append(qb)

                space = new_space

                jumped_space = {}
                for (p, q), qubits in space.items():
                    if (p, q) in wormholes:
                        for qb in qubits:
                            if qb.has_history:
                                p_dest = (p + (q - qb.q_prev) * qb.v) % N
                                q_dest = (q + (p - qb.p_prev) * qb.v) % N

                                qb.p = p_dest
                                qb.q = q_dest

                                loc = (p_dest, q_dest)
                                if loc not in jumped_space:
                                    jumped_space[loc] = []
                                jumped_space[loc].append(qb)
                            else:
                                loc = (qb.p, qb.q)
                                if loc not in jumped_space:
                                    jumped_space[loc] = []
                                jumped_space[loc].append(qb)
                    else:
                        for qb in qubits:
                            loc = (qb.p, qb.q)
                            if loc not in jumped_space:
                                jumped_space[loc] = []
                            jumped_space[loc].append(qb)

                space = jumped_space

                final_space = {}
                for (p, q), qubits in space.items():
                    k = len(qubits)
                    if k == 0:
                        continue
                    if k == 1:
                        final_space[(p, q)] = qubits
                        continue

                    sum_E = sum(qb.E for qb in qubits)
                    sum_v = sum(qb.v for qb in qubits)

                    def sort_key_A(x):
                        return (-x.E, -x.v, x.theta)

                    new_qubits_here = []

                    if sum_E > k * Phi:
                        k_new = k - (k % 2)
                        if k_new > 0:
                            E_new = sum_E // k_new
                            prior_A = min(qubits, key=sort_key_A)
                            v_new = prior_A.v

                            if E_new >= 1 and v_new >= 1:
                                sum_cos = 0.0
                                sum_sin = 0.0
                                for qb in qubits:
                                    alpha = qb.theta * math.pi / 4.0
                                    sum_cos += math.cos(alpha)
                                    sum_sin += math.sin(alpha)
                                avg_x = sum_cos / k
                                avg_y = sum_sin / k
                                alpha_mean = math.atan2(avg_y, avg_x)

                                theta_base = (math.floor(alpha_mean * 4.0 / math.pi + 0.5) + 8) % 8

                                for i in range(k_new):
                                    th = (theta_base + i) % 8
                                    new_qubits_here.append(Qubit(p, q, E_new, v_new, th, has_history=False))

                    elif sum_v > (sum_E // k):
                        prior_B = min(qubits, key=lambda x: (x.E, x.v, x.theta))
                        E_cat, v_cat, th_cat = prior_B.E, prior_B.v, prior_B.theta
                        E_new = (sum_E - E_cat) // (2 * k)
                        v_new = v_cat

                        if E_new >= 1 and v_new >= 1:
                            for i in range(2 * k):
                                th = (th_cat + 2 * i) % 8
                                new_qubits_here.append(Qubit(p, q, E_new, v_new, th, has_history=False))

                    else:
                        prior_A = min(qubits, key=sort_key_A)
                        E_new = sum_E - sum_v
                        v_new = sum_v // k

                        if E_new >= 1 and v_new >= 1:
                            new_qubits_here.append(Qubit(p, q, E_new, v_new, prior_A.theta, has_history=False))

                    if new_qubits_here:
                        final_space[(p, q)] = new_qubits_here

                space = final_space

        elif type_q == 2:
            p = int(next(iterator))
            q = int(next(iterator))
            E = int(next(iterator))
            v = int(next(iterator))
            theta = int(next(iterator))
            if (p, q) not in space:
                space[(p, q)] = []
            space[(p, q)].append(Qubit(p, q, E, v, theta, has_history=False))

        elif type_q == 3:
            p = int(next(iterator))
            q = int(next(iterator))
            if (p, q) in space and space[(p, q)]:
                def sort_key_A(x):
                    return (-x.E, -x.v, x.theta)
                prior_A = min(space[(p, q)], key=sort_key_A)
                print(f"{prior_A.E} {prior_A.v} {prior_A.theta}")

        elif type_q == 4:
            p1 = int(next(iterator))
            q1 = int(next(iterator))
            p2 = int(next(iterator))
            q2 = int(next(iterator))
            D = int(next(iterator))
            D8 = D % 8

            for (p, q), qubits in space.items():
                if in_range(p, p1, p2) and in_range(q, q1, q2):
                    for qb in qubits:
                        qb.theta = (qb.theta + D8) % 8

        elif type_q == 5:
            total_E = sum(qb.E for qubits in space.values() for qb in qubits)
            print(total_E)

        elif type_q == 6:
            p = int(next(iterator))
            q = int(next(iterator))
            if (p, q) in space and space[(p, q)]:
                prior_B = min(space[(p, q)], key=lambda x: (x.E, x.v, x.theta))
                space[(p, q)].remove(prior_B)
                if not space[(p, q)]:
                    del space[(p, q)]


if __name__ == '__main__':
    solve()
